In Go, the usual way is to use `bufio.Scanner` to read a file line by line:

```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

func countLines(filename string) (int, error) {
	file, err := os.Open(filename)
	if err != nil {
		return 0, err
	}
	defer file.Close()

	count := 0
	scanner := bufio.NewScanner(file)

	for scanner.Scan() {
		count++
	}

	if err := scanner.Err(); err != nil {
		return 0, err
	}

	return count, nil
}

func main() {
	count, err := countLines("example.txt")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	fmt.Println("Line count:", count)
}
```

